CREATE TABLE fts_ranking (
      id serial PRIMARY KEY,
      title text,
      body text
    );

SELECT title, ts_rank_cd(to_tsvector('simple', body), to_tsquery('simple', 'fat & rat')) as rank
    FROM fts_ranking
    ORDER BY rank DESC, id;

